def regex_match(s, p):
    m, n = len(s), len(p)

    # dp[i][j] represents whether s[0:i] matches p[0:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Empty string matches empty pattern
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* that can match empty string
    for j in range(2, n + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j-1] == '*':
                # Zero occurrence of preceding element OR one/more occurrences
                dp[i][j] = dp[i][j-2] or (dp[i-1][j] and (s[i-1] == p[j-2] or p[j-2] == '.'))
            elif p[j-1] == '.' or s[i-1] == p[j-1]:
                # Direct match or dot matching any character
                dp[i][j] = dp[i-1][j-1]

    return dp[m][n]

n_queens:
def n_queens(n):
    def is_safe(board, row, col):
        # Check this column
        for i in range(row):
            if board[i] == col:
                return False

        # Check upper left diagonal
        for i in range(row):
            if board[i] == col - (row - i):
                return False

        # Check upper right diagonal
        for i in range(row):
            if board[i] == col + (row - i):
                return False

        return True

    def backtrack(board, row):
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                count += backtrack(board, row + 1)

        return count

    return backtrack([0] * n, 0)

