def calculate(s):
    def helper(s, index):
        stack = []
        num = 0
        op = '+'

        while index < len(s):
            c = s[index]

            if c.isdigit():
                num = num * 10 + int(c)

            if c == '(':
                num, index = helper(s, index + 1)

            if index == len(s) - 1 or c in '+-*/)' or c == ' ' and s[index+1] in '+-*/':
                if op == '+':
                    stack.append(num)
                elif op == '-':
                    stack.append(-num)
                elif op == '*':
                    stack.append(stack.pop() * num)
                elif op == '/':
                    prev = stack.pop()
                    if prev < 0:
                        stack.append(-(-prev // num))
                    else:
                        stack.append(prev // num)

                if c == ')':
                    break

                op = c
                num = 0

            index += 1

        return sum(stack), index

    result, _ = helper(s, 0)
    return result

