longest_palindrome_subseq:
def longest_palindrome_subseq(s):
    n = len(s)
    if n == 0:
        return 0

    # dp[i][j] represents the length of longest palindromic subsequence in s[i:j+1]
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table for subsequences of length 2 to n
    for length in range(2, n + 1):  # length of subsequence
        for i in range(n - length + 1):  # starting index
            j = i + length - 1  # ending index

            if s[i] == s[j]:
                # If characters match, add 2 to the result of inner subsequence
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                # If characters don't match, take maximum of excluding either character
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

max_profit_k:
def max_profit_k(k, prices):
    if not prices or k == 0:
        return 0

    n = len(prices)
    if k >= n // 2:
        # If k is large enough, use greedy approach
        profit = 0
        for i in range(1, n):
            if prices[i] > prices[i-1]:
                profit += prices[i] - prices[i-1]
        return profit

    # dp[i][j] represents max profit with at most i transactions up to day j
    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -prices[0]  # max value of (dp[i-1][t] - prices[t])
        for j in range(1, n):
            dp[i][j] = max(dp[i][j-1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i-1][j] - prices[j])

    return dp[k][n-1]

word_ladder:
from collections import deque

def word_ladder(begin, end, words):
    if end not in words:
        return 0

    words_set = set(words)
    queue = deque([(begin, 1)])
    visited = set([begin])

    while queue:
        current_word, length = queue.popleft()

        if current_word == end:
            return length

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c == current_word[i]:
                    continue
                new_word = current_word[:i] + c + current_word[i+1:]
                if new_word in words_set and new_word not in visited:
                    visited.add(new_word)
                    queue.append((new_word, length + 1))

    return 0

eval_rpn:
def eval_rpn(tokens):
    stack = []
    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # token == "/"
                stack.append(int(a / b))  # int() truncates toward zero
        else:
            stack.append(int(token))
    return stack[0]
